=head2 Google::Cloud::Configdelivery::V1beta::ConfigDelivery::FleetPackage

A `FleetPackage` resource in the Config Delivery API.

A `FleetPackage` defines a package through which kubernetes
configuration is deployed to a fleet of kubernetes clusters.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Identifier. Name of the `FleetPackage`. Format is
`projects/{project}/locations/{location}/fleetPackages/{fleetPackage}`.
The `fleetPackage` component must match
`[a-z][a-z0-9\-]{0,62}`

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Time at which the `FleetPackage` was created.

=item * C<< $msg->update_time() >> / C<< $msg->update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Most recent time at which the `FleetPackage` was updated.

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Cloud::Configdelivery::V1beta::ConfigDelivery::FleetPackage::LabelsEntry>)

Optional. Labels are attributes that can be set and used by both the
user and by Config Delivery. Labels must meet the following constraints:

* Keys and values can contain only lowercase letters, numeric characters,
underscores, and dashes.
* All characters must use UTF-8 encoding, and international characters are
allowed.
* Keys must start with a lowercase letter or international character.
* Each resource is limited to a maximum of 64 labels.

Both keys and values are additionally constrained to be <= 128 bytes.

=item * C<< $msg->resource_bundle_selector() >> / C<< $msg->resource_bundle_selector($value) >>

Type: C<Message> (L<Google::Cloud::Configdelivery::V1beta::ConfigDelivery::FleetPackage::ResourceBundleSelector>)

Required. Information specifying the source of kubernetes configuration to
deploy.

=item * C<< $msg->target() >> / C<< $msg->target($value) >>

Type: C<Message> (L<Google::Cloud::Configdelivery::V1beta::ConfigDelivery::FleetPackage::Target>)

Optional. Configuration to select target clusters to deploy kubernetes
configuration to.

=item * C<< $msg->rollout_strategy() >> / C<< $msg->rollout_strategy($value) >>

Type: C<Message> (L<Google::Cloud::Configdelivery::V1beta::ConfigDelivery::RolloutStrategy>)

Optional. The strategy to use to deploy kubernetes configuration to
clusters.

=item * C<< $msg->variant_selector() >> / C<< $msg->variant_selector($value) >>

Type: C<Message> (L<Google::Cloud::Configdelivery::V1beta::ConfigDelivery::FleetPackage::VariantSelector>)

Required. Information specifying how to map a `ResourceBundle` variant to a
target cluster.

=item * C<< $msg->info() >> / C<< $msg->info($value) >>

Type: C<Message> (L<Google::Cloud::Configdelivery::V1beta::ConfigDelivery::FleetPackageInfo>)

Output only. Information containing the rollout status of the
`FleetPackage` across all the target clusters.

=item * C<< $msg->deletion_propagation_policy() >> / C<< $msg->deletion_propagation_policy($value) >>

Type: C<Enum> (L<Google::Cloud::Configdelivery::V1beta::DeletionPropagationPolicy>)

Optional. Information around how to handle kubernetes resources at the
target clusters when the `FleetPackage` is deleted.

=item * C<< $msg->state() >> / C<< $msg->state($value) >>

Type: C<Enum> (L<Google::Cloud::Configdelivery::V1beta::FleetPackage::State>)

Optional. The desired state of the fleet package.

=back

