rollout.

=item * C<< $msg->rollout_strategy_info() >> / C<< $msg->rollout_strategy_info($value) >>

Type: C<Message> (L<Google::Cloud::Configdelivery::V1beta::ConfigDelivery::RolloutStrategyInfo>)

