rollout strategy.

=back

=head3 Enum: RolloutInfo::State

=over 4

=item * C<STATE_UNSPECIFIED> => C<0>

=item * C<COMPLETED> => C<1>

=item * C<SUSPENDED> => C<2>

=item * C<ABORTED> => C<3>

=item * C<IN_PROGRESS> => C<5>

=item * C<STALLED> => C<6>

=item * C<CANCELLED> => C<7>

=item * C<ABORTING> => C<8>

=back

=head2 Google::Cloud::Configdelivery::V1beta::ConfigDelivery::Rollout

Rollout resource represents an instance of `FleetPackage` rollout operation
across a fleet. This is a system generated resource and will be read only for
end-users. It will be primarily used by the service to process the changes in
the `FleetPackage` and other changes in the environment.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Identifier. Name of the Rollout. Format is
`projects/{project}/locations/{location}/fleetPackages/{fleet_package}/rollouts/[a-z][a-z0-9\-]{0,62}`.

=item * C<< $msg->release() >> / C<< $msg->release($value) >>

Type: C<String>

Reference to the `Release` being rolled out.

=item * C<< $msg->rollout_strategy() >> / C<< $msg->rollout_strategy($value) >>

Type: C<Message> (L<Google::Cloud::Configdelivery::V1beta::ConfigDelivery::RolloutStrategy>)

Rollout strategy for rolling out `FleetPackage` to clusters.

=item * C<< $msg->info() >> / C<< $msg->info($value) >>

Type: C<Message> (L<Google::Cloud::Configdelivery::V1beta::ConfigDelivery::RolloutInfo>)

Current details of the rollout.

=item * C<< $msg->deletion_propagation_policy() >> / C<< $msg->deletion_propagation_policy($value) >>

Type: C<Enum> (L<Google::Cloud::Configdelivery::V1beta::DeletionPropagationPolicy>)

Deletion propagation policy of the rollout.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The time the rollout was created.

=item * C<< $msg->update_time() >> / C<< $msg->update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The time the rollout was most recently updated.

=back

